"""Parsing parcels from text."""
from parcels import Parcel


def _parse_line(line):
    depot, grams = line.split(",")
    return Parcel(depot.strip(), int(grams))


def parse_parcels(text):
    """Parse lines of 'depot,grams' into Parcel records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def group_by_depot(parcels):
    """Return a dict from depot to the list of parcels with that depot."""
    groups = {}
    for x in parcels:
        groups.setdefault(x.depot, []).append(x)
    return groups

